"""Build a static, local image-and-Chinese-script review page; never renders video."""
from pathlib import Path
import json,html,hashlib,struct
p=Path(__file__).resolve().parents[1]
d=json.loads((p/'shots.plan.json').read_text())
assets=[];cards=[];md=['# 早孕可能出现的8个信号 · 全分镜图文审阅 v2\n','状态：待用户确认。约80秒、13镜。没有启动本期配音/H3/剪辑/视频渲染。\n','图片由OpenLux GPT Image 2基于已认可角色和同场景首帧编辑；视频计划为220 H3，精确中文由Remotion后期添加。以下为原始参考帧，尚无动态效果。\n']
for x in d['shots']:
 f=p/x['planned_reference']
 if not f.exists():raise FileNotFoundError(f)
 raw=f.read_bytes();w,h=struct.unpack('>II',raw[16:24]);sha=hashlib.sha256(raw).hexdigest()
 x['reference_image']=x['planned_reference'];x['reference_sha256']=sha;x['actual_size']=[w,h];x['review_status']='awaiting_user_review'
 assets.append({'shot_id':x['id'],'path':x['reference_image'],'sha256':sha,'bytes':len(raw),'actual_size':[w,h],'requested_size':[1152,2048],'size_mismatch':(w,h)!=(1152,2048),'input':x['source_reference'],'input_sha256':hashlib.sha256((p/x['source_reference']).read_bytes()).hexdigest(),'provider':'OpenLux','model':'gpt-image-2','image_prompt':x["image_prompt_file"],'motion_prompt':f"prompts/shots/shot_{x['id']}_motion_v1.txt"})
 E=html.escape
 cards.append(f'''<article id="shot-{x['id']}"><a class="picture" href="{E(x['reference_image'])}" target="_blank"><img src="{E(x['reference_image'])}" alt="第{x['id']}镜 {E(x['name'])}" loading="lazy"></a><section><span class="eyebrow">SHOT {x['id']} · {x['target_seconds']} 秒 · {E(x['scene_id'])}</span><h2>{E(x['name'])}</h2><h3>中文旁白</h3><p class="voice">{E(x['narration'])}</p><h3>屏幕文字（后期添加）</h3><p class="screen">{E(x['screen_text'])}</p><p class="small">{E(x["text_layout"])}</p><h3>动作与运镜</h3><p>{E(x['action'])}；{E(x['camera'])}。</p><p class="small">原图 {w}×{h} · 点击图片查看原图<br>参考帧：OpenLux GPT Image 2<br>动态计划：220 MiniMax H3；文字与合成：Remotion</p><details><summary>查看图像与动作提示词</summary><h3>图片 prompt</h3><p>{E(x['image_prompt'])}</p><h3>H3 prompt（尚未执行）</h3><p>{E(x['motion_prompt'])}</p></details></section></article>''')
 md += [f"## {x['id']} {x['name']} · {x['target_seconds']}秒\n",f"![{x['name']}]({f})\n",f"**中文旁白**：{x['narration']}\n",f"**屏幕文字**：{x['screen_text']}\n",f"**动作 / 运镜**：{x['action']}；{x['camera']}。\n",f"原图：{w}×{h}；图片及H3 prompt见 shots.plan.json。\n"]
nav=''.join(f'<a href="#shot-{x["id"]}">{x["id"]} {html.escape(x["name"])}</a>' for x in d['shots'])
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>奶油绘本科普 · 13镜图文审阅</title><style>*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f7f2e8;color:#493b30;font:16px/1.8 -apple-system,BlinkMacSystemFont,"PingFang SC",sans-serif}header,main{max-width:1160px;margin:auto;padding:30px}header{padding-top:55px}h1{font-size:36px;line-height:1.3}h2{font-size:29px;margin:8px 0 24px}h3{font-size:14px;color:#876f55;margin:24px 0 6px}p{margin:0 0 12px}nav{display:flex;gap:8px;flex-wrap:wrap;margin-top:24px}nav a{background:#fff9ee;border:1px solid #dfcdb5;border-radius:24px;padding:5px 13px;color:inherit;text-decoration:none;font-size:13px}article{display:grid;grid-template-columns:minmax(240px,42%) 1fr;gap:34px;background:#fffdf7;border-radius:20px;padding:25px;margin-bottom:30px;scroll-margin-top:20px;box-shadow:0 5px 24px #573d2010}.picture{display:block}.picture img{width:100%;display:block;border-radius:10px}section{padding:12px 5px}.eyebrow,.small{font-size:13px;color:#8a7867}.voice{font-size:21px}.screen{background:#fff0c6;padding:12px 16px;border-radius:10px}details{font-size:12px;overflow-wrap:anywhere;margin-top:20px}summary{cursor:pointer}.tag{background:#e2ebdf;padding:5px 12px;border-radius:8px;display:inline-block}.notice{border-left:3px solid #c99b78;padding-left:16px;max-width:920px}@media(max-width:700px){header,main{padding:18px}h1{font-size:28px}article{grid-template-columns:1fr;padding:16px;gap:10px}.voice{font-size:19px}.picture{max-width:400px;margin:auto}}@media print{article{break-inside:avoid;box-shadow:none}nav,details{display:none}}</style><header><span class="tag">全分镜参考帧＋中文文案 · 待确认</span><h1>早孕可能出现的 8 个信号</h1><p>奶油绘本科普 / 13 镜 / 预计 80 秒</p><p class="notice">这里展示的是完整静态参考帧，还没有生成本期视频。请重点看人物、背景物品、画面表达与旁白是否合适；中文标题和字幕将在后期添加。全部图文确认后，才进入配音与 H3 制作。实际返回尺寸见各镜，未冒充原生1080p。</p><p>每个房间沿用共同的配色与家具设计。下方图片可点击放大；修改时直接报镜头编号。</p><nav>'''+nav+'</nav></header><main>'+''.join(cards)+'</main></html>'
(p/'REVIEW.html').write_text(page)
(p/'REVIEW.md').write_text('\n'.join(md))
d['status']='storyboard_review_pending';(p/'shots.plan.json').write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
(p/'frames-manifest.json').write_text(json.dumps({'status':'storyboard_review_pending','assets':assets},ensure_ascii=False,indent=2)+'\n')
print(f'Built review for {len(assets)} frames; all inputs and outputs hashed.')
